	ll v[N];
	ll dp[K+1][M+1];
	ll cdp[M+1];
	ll tgt;
	string ans="";
	cin>>n>>m;
	rep(i,n)cin>>p[i]>>v[i];


	rep(j,m+1)cdp[j]=0;
	rep(i,n){
		for(int j=m;j>=p[i];j--)cdp[j]=max(cdp[j],cdp[j-p[i]]+v[i]);
	}
	tgt=cdp[m];
	rep(i,n)ans+='X';

	rep(j,m+1)dp[0][0]=0;
	rep(k,(n-1)/K+1){
		r=n-k*K-1;
		l=max(n-k*K-K,0);
		for(int i=r;i>=l;i--){
			rep(j,M+1){
				dp[r-i+1][j]=dp[r-i][j];
				if(j>=p[i])dp[r-i+1][j]=max(dp[r-i+1][j],dp[r-i][j-p[i]]+v[i]);
			}
		}

		rep(j,m+1)cdp[j]=0;
		rep(i,l){
			for(int j=m;j>=p[i];j--)cdp[j]=max(cdp[j],cdp[j-p[i]]+v[i]);
		}
		for(int i=l;i<=r;i++){
			ll mx_woi=0;
			rep(j,m+1)mx_woi=max(mx_woi,cdp[j]+dp[r-i][m-j]);
			ll mx_wi=0;
			rep(j,m-p[i]+1)mx_wi=max(mx_wi,cdp[j]+dp[r-i][m-p[i]-j]);
			if(mx_woi<tgt)ans[i]='A';
			else if(mx_wi<tgt-v[i])ans[i]='C';
			else ans[i]='B';
			if(i==r)break;
			for(int j=m;j>=p[i];j--)cdp[j]=max(cdp[j],cdp[j-p[i]]+v[i]);
		}
		if(l>0){
			rep(j,M+1)dp[0][j]=dp[K][j];
		}
	}

	cout<<ans<<endl;

	return 0;
